class Parent {
    int x = 4;
    int read() { return x + 1; }
}
class Child extends Parent {
    int x = 9;
    @Override int read() { return x * 2; }
}
public class Main {
    public static void main(String[] args) {
        Parent p = new Child();
        Child c = (Child)p;
        System.out.print(p.x + ":" + p.read() + ":" + c.x);
    }
}

class Base {
    int x;
    Base(int x) {
        this.x = x;
        System.out.print("P" + x);
    }
    int value() { return x + 2; }
}
class Child extends Base {
    int x;
    Child(int v) {
        super(v + 1);
        this.x = v;
        System.out.print("C" + x);
    }
    int value(int add) { return super.value() + add; }
}
public class Main {
    public static void main(String[] args) {
        Child c = new Child(4);
        Base p = c;
        System.out.print("|" + p.value() + ":" + c.value(3));
    }
}

public class Main {
    static int calls = 0;
    static int calc(int n) {
        ++calls;
        if (n <= 1) return n;
        int a = calc(n - 2);
        int b = calc(n - 3);
        return a + b;
    }
    public static void main(String[] args) {
        int first = calc(5);
        int second = calc(4);
        System.out.print(first + ":" + second + ":" + calls);
    }
}

